{
  "findings": [
    {
      "check_id": "CKV_AZURE_13",
      "title": "Plaintext administrator password in configuration",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "CRITICAL",
      "explanation": "Storing sensitive information like administrator passwords in plaintext within Terraform files poses a significant security risk. It can lead to unauthorized access if the file is exposed."
    },
    {
      "check_id": "CKV_AZURE_12",
      "title": "Missing minimal TLS version enforcement",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "HIGH",
      "explanation": "The `minimal_tls_version` attribute is not set, which means the server may accept insecure TLS versions. This increases the risk of data interception or man-in-the-middle attacks."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server\" \"changeme_simple_mssql_server\" {\n  name                = \"changeme-simple-mssql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location\n  version             = \"12.0\"\n\n  administrator_login = \"changemeadmin\"\n  administrator_login_password = var.administrator_login_password\n\n  minimal_tls_version = \"1.2\"\n}\n\nvariable \"administrator_login_password\" {\n  description = \"The administrator login password for the SQL server.\"\n  type        = string\n  sensitive   = true\n}",
  "fix_summary": "Moved the administrator password to a sensitive variable to avoid plaintext exposure and enforced a minimum TLS version of 1.2 for secure communication."
}
